def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    # Check if we are in exploit mode: we defected, opponent cooperated next, and has cooperated ever since.
    exploit = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            all_c = True
            for j in range(i + 1, n):
                if history[j][1] != 'C':
                    all_c = False
                    break
            if all_c:
                exploit = True
                break

    if exploit:
        return 'D'

    opp_d = 0
    opp_streak = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    if n >= 95 and opp_streak > 0:
        return 'D'
    if opp_streak > 4:
        return 'D'
    opp_rate = opp_d / n
    if n >= 10 and opp_rate > 0.35:
        return 'D'
    if opp_streak > 0:
        return 'C'

    my_last = history[-1][0]
    if my_last == 'D':
        return 'C'

    ever_defected = any(h[0] == 'D' for h in history)
    if not ever_defected and n == 20:
        return 'D'
    return 'C'
